# General Science: life sciences to class 10 level (cells and tissues, life processes,
# control and coordination, reproduction, heredity and evolution, health and our
# environment). Key first.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Nutrition", "Which of these organisms makes its own food by photosynthesis?",
      ["Grass", "Mushroom", "Tapeworm", "Amoeba"],
      "Green plants are autotrophs: they make food from carbon dioxide and water using sunlight. A mushroom is a saprophyte, a tapeworm a parasite and amoeba takes in ready-made food."),
    S(1, 2, "Digestion", "Which enzyme in pancreatic juice digests proteins?",
      ["Trypsin", "Lipase", "Amylase", "Pepsin"],
      "Pancreatic juice contains trypsin for proteins and lipase for fats (and amylase for starch). Pepsin also digests proteins, but it is made in the stomach, not the pancreas."),
    S(1, 2, "Respiration", "During hard exercise, muscle cells short of oxygen break down glucose anaerobically. Which substance builds up and causes cramps?",
      ["Lactic acid", "Ethanol", "Glucose", "Acetic acid"],
      "Without enough oxygen, pyruvate in muscle cells is turned into lactic acid, which causes cramps. Yeast, in contrast, makes ethanol and carbon dioxide."),
    S(1, 2, "Control and coordination", "Where in the body is a reflex arc, such as pulling the hand away from a hot object, mainly formed?",
      ["Spinal cord", "Cerebrum", "Cerebellum", "Hypothalamus"],
      "In a reflex the message goes from the sensory nerve to the spinal cord and straight back along a motor nerve, so the response is quick and does not wait for the brain to think."),
    S(1, 2, "Reproduction", "Where does fertilisation of the egg normally take place in the human female?",
      ["Fallopian tube", "Uterus", "Ovary", "Cervix"],
      "The egg released by the ovary meets the sperm in the fallopian tube (oviduct). The fertilised egg then moves to the uterus and is implanted in its wall."),
    S(1, 3, "Heredity", "In Mendel's dihybrid cross of pea plants, what is the phenotypic ratio in the F2 generation?",
      ["9 : 3 : 3 : 1", "3 : 1", "1 : 2 : 1", "1 : 1 : 1 : 1"],
      "Crossing two traits (for example round yellow and wrinkled green seeds) gives 9 with both dominant traits, 3 and 3 with one of each, and 1 with both recessive traits."),
    S(1, 1, "Our environment", "In the food chain grass → grasshopper → frog → snake, which organism is the secondary consumer?",
      ["Frog", "Grasshopper", "Snake", "Grass"],
      "Grass is the producer, the grasshopper (a herbivore) the primary consumer, the frog that eats it the secondary consumer and the snake the tertiary consumer."),
    S(1, 2, "Plant hormones", "Which plant hormone inhibits growth and causes the stomata to close when water is short?",
      ["Abscisic acid", "Gibberellin", "Cytokinin", "Indole acetic acid"],
      "Abscisic acid is the stress hormone of plants: it slows growth, closes stomata and causes leaves to wilt and fall. Indole acetic acid is an auxin, which promotes growth."),

    # ---------- Practice Test 2 ----------
    S(2, 1, "Tissues", "Which tissue joins one bone to another bone?",
      ["Ligament", "Tendon", "Cartilage", "Areolar tissue"],
      "Ligaments are strong, slightly elastic tissue that hold bones together at joints. Tendons join muscles to bones."),
    S(2, 1, "The cell", "Who first observed and named cells, in a thin slice of cork in 1665?",
      ["Robert Hooke", "Robert Brown", "Rudolf Virchow", "Matthias Schleiden"],
      "Robert Hooke saw tiny box-like compartments in cork with his microscope and called them cells. Robert Brown discovered the nucleus in 1831."),
    S(2, 1, "Nutrition", "How does an amoeba take in its food?",
      ["With pseudopodia", "With cilia", "With a flagellum", "With tentacles"],
      "Amoeba pushes out finger-like projections of its body called pseudopodia, which surround the food particle and form a food vacuole where it is digested."),
    S(2, 2, "Circulation", "Human blood circulation is called 'double circulation' because:",
      ["Blood passes through the heart twice in each cycle", "The heart beats twice for every breath that is taken", "Blood flows out through two arteries at the same time", "There are two kinds of blood cells in it"],
      "Blood goes heart → lungs → heart (pulmonary circulation) and then heart → body → heart (systemic circulation). Keeping oxygen-rich and oxygen-poor blood apart gives a good supply of oxygen."),
    S(2, 1, "Health", "Which disease is caused by a virus that attacks the body's immune system?",
      ["AIDS", "Cholera", "Typhoid", "Malaria"],
      "AIDS is caused by HIV, which destroys the white blood cells that fight infection. Cholera and typhoid are caused by bacteria, and malaria by a protozoan."),
    S(2, 2, "Reproduction", "In the potato, new plants grow by vegetative propagation from which part?",
      ["Stem tuber", "Root", "Leaf", "Seed"],
      "A potato is a swollen underground stem (a tuber). Its buds, the 'eyes', grow into new plants. Sweet potato, in contrast, is a root."),
    S(2, 2, "Evolution", "The forelimbs of a frog, a bird and a human have the same basic structure but different uses. Such organs are called:",
      ["Homologous organs", "Analogous organs", "Vestigial organs", "Fossil organs"],
      "Homologous organs share an origin and basic design but do different jobs, which is evidence of common ancestry. Analogous organs, like the wings of a bird and an insect, do the same job but are built differently."),
    S(2, 2, "Health", "Antibiotics such as penicillin are effective against diseases caused by:",
      ["Bacteria", "Viruses", "Allergies", "Vitamin deficiencies"],
      "Antibiotics block processes that bacteria need, such as building their cell wall. Viruses have no such processes, so antibiotics do not cure viral illnesses like the common cold or flu."),

    # ---------- Drill only ----------
    S(0, 2, "Excretion", "Which part of the nephron filters the blood?",
      ["Glomerulus", "Loop of Henle", "Collecting duct", "Ureter"],
      "The glomerulus is a tuft of capillaries inside Bowman's capsule; water, salts, glucose and urea are filtered out of the blood there. Useful substances are reabsorbed further along the tubule."),
    S(0, 2, "Photosynthesis", "The oxygen given off by green plants during photosynthesis comes from:",
      ["Water", "Carbon dioxide", "Chlorophyll", "Glucose"],
      "In the light reaction water molecules are split, releasing oxygen. The carbon dioxide is built into glucose."),
    S(0, 1, "Hormones", "A lack of the hormone insulin causes which disease?",
      ["Diabetes", "Goitre", "Dwarfism", "Anaemia"],
      "Insulin, made in the pancreas, lowers blood sugar. Without enough of it, blood sugar stays high: diabetes."),
    S(0, 2, "Respiration", "In which part of the cell is glucose first broken down into pyruvate?",
      ["Cytoplasm", "Mitochondria", "Nucleus", "Chloroplast"],
      "Glycolysis, the splitting of glucose into pyruvate, happens in the cytoplasm. With oxygen, pyruvate is then broken down completely in the mitochondria."),
    S(0, 1, "Reproduction in plants", "What is the transfer of pollen from the anther to the stigma called?",
      ["Pollination", "Fertilisation", "Germination", "Transpiration"],
      "Pollination may be by wind, water, insects or birds. Fertilisation comes later, when the male gamete from the pollen fuses with the egg in the ovule."),
    S(0, 2, "Circulation", "Which of these animals has a three-chambered heart?",
      ["Frog", "Fish", "Pigeon", "Cow"],
      "Amphibians such as frogs have two atria and one ventricle. Fish have two chambers, and birds and mammals four."),
    S(0, 1, "Digestion", "The villi in the small intestine increase the surface area for:",
      ["Absorption of digested food", "Production of bile", "Storage of undigested food", "Secretion of hydrochloric acid"],
      "The many finger-like villi, each rich in blood vessels, give a huge surface through which digested food passes into the blood."),
    S(0, 2, "Sense organs", "Which part of the human ear changes sound vibrations into nerve impulses?",
      ["Cochlea", "Eardrum", "Pinna", "Eustachian tube"],
      "The fluid-filled, snail-shaped cochlea in the inner ear has hair cells that turn vibrations into nerve impulses, carried to the brain by the auditory nerve."),
]
